class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `${this.name} (Mana: ${this.manaCost}) is cast without specific effect.`;
  }
}

class Fireball extends Spell {
  constructor(name, manaCost) {
    super(name, manaCost);
  }

  cast() {
    return `Casting ${this.name} for ${this.manaCost} mana, dealing fiery damage!`;
  }
}

class HealSpell extends Spell {
  constructor(name, manaCost) {
    super(name, manaCost);
  }

  cast() {
    return `Casting ${this.name} for ${this.manaCost} mana, restoring health!`;
  }
}

// --- Test Cases ---
const fireball = new Fireball("Greater Fireball", 30);
const heal = new HealSpell("Minor Heal", 15);

console.log(fireball.cast());
console.log(heal.cast());

